function testPeek() {
  console.log("Testing peek method...");

  const cache = new Cache(3);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);

  // Test peek on existing key
  const value = cache.peek('b');
  if (value !== 2) {
    console.error("FAIL: peek should return the correct value");
    return false;
  }

  // Test that peek doesn't affect LRU order
  // Access 'a' to make it most recently used
  cache.get('a');

  // Peek 'c' - should still be in the same position
  const value2 = cache.peek('c');
  if (value2 !== 3) {
    console.error("FAIL: peek should return the correct value");
    return false;
  }

  // Verify LRU order is still correct (a should be first, then c, then b)
  const keys = cache.keys();
  if (keys[0] !== 'a' || keys[1] !== 'c' || keys[2] !== 'b') {
    console.error("FAIL: LRU order should not be affected by peek");
    return false;
  }

  // Test peek on non-existing key
  const value3 = cache.peek('nonexistent');
  if (value3 !== undefined) {
    console.error("FAIL: peek should return undefined for non-existing key");
    return false;
  }

  console.log("PASS: peek method works correctly");
  return true;
}

// Run all tests
console.log("Running Cache delete and clear tests...\n");

let allPassed = true;
allPassed &= testDelete();
allPassed &= testClear();
allPassed &= testDeleteWithLRU();
allPassed &= testKeys();
allPassed &= testPeek();

if (allPassed) {
  console.log("\nAll tests passed!");
} else {
  console.log("\nSome tests failed!");
  process.exit(1);
}

const { Cache } = require('./s7_cache.js');

function testDelete() {
  console.log("Testing delete method...");

  const cache = new Cache(2);
  cache.set('a', 1);
  cache.set('b', 2);

  // Test deleting existing key
  const result1 = cache.delete('a');
  if (result1 !== true) {
    console.error("FAIL: delete should return true when removing existing key");
    return false;
  }

  // Test that key is actually removed
  if (cache.has('a')) {
    console.error("FAIL: key should be removed from cache");
    return false;
  }

  // Test deleting non-existing key
  const result2 = cache.delete('nonexistent');
  if (result2 !== false) {
    console.error("FAIL: delete should return false when removing non-existing key");
    return false;
  }

  console.log("PASS: delete method works correctly");
  return true;
}

function testClear() {
  console.log("Testing clear method...");

  const cache = new Cache(3);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);

  // Verify cache has items
  if (cache.size() !== 3) {
    console.error("FAIL: cache should have 3 items before clear");
    return false;
  }

  // Clear the cache
  cache.clear();

  // Verify cache is empty
  if (cache.size() !== 0) {
    console.error("FAIL: cache should be empty after clear");
    return false;
  }

  // Verify all keys are removed
  if (cache.has('a') || cache.has('b') || cache.has('c')) {
    console.error("FAIL: all keys should be removed after clear");
    return false;
  }

  console.log("PASS: clear method works correctly");
  return true;
}

function testDeleteWithLRU() {
  console.log("Testing delete with LRU behavior...");

  const cache = new Cache(3);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);

  // Access 'a' to make it most recently used
  cache.get('a');

  // Delete 'b' (middle item)
  const result = cache.delete('b');
  if (result !== true) {
    console.error("FAIL: delete should return true for existing key");
    return false;
  }

  // Verify 'b' is removed but 'a' and 'c' still exist
  if (!cache.has('a') || !cache.has('c') || cache.has('b')) {
    console.error("FAIL: only 'b' should be removed");
    return false;
  }

  console.log("PASS: delete works correctly with LRU");
  return true;
}

function testKeys() {
  console.log("Testing keys method...");

  const cache = new Cache(3);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);

  // Test that keys are returned in LRU order (most recent first)
  const keys = cache.keys();
  if (keys.length !== 3) {
    console.error("FAIL: keys should return 3 items");
    return false;
  }

  // Check order: c (most recent), b, a (least recent)
  if (keys[0] !== 'c' || keys[1] !== 'b' || keys[2] !== 'a') {
    console.error("FAIL: keys should be in LRU order (most recent first)");
    return false;
  }

  // Access 'a' to make it most recently used
  cache.get('a');

  // Test that order is updated
  const keys2 = cache.keys();
  if (keys2[0] !== 'a' || keys2[1] !== 'c' || keys2[2] !== 'b') {
    console.error("FAIL: keys order should update after get operation");
    return false;
  }

  // Add a new item to test eviction
  cache.set('d', 4);

  // Test that old item was evicted and new order is correct
  const keys3 = cache.keys();
  if (keys3.length !== 3) {
    console.error("FAIL: keys should still return 3 items after eviction");
    return false;
  }

  if (keys3[0] !== 'd' || keys3[1] !== 'a' || keys3[2] !== 'c') {
    console.error("FAIL: keys should reflect LRU after eviction");
    return false;
  }

  console.log("PASS: keys method works correctly");
  return true;
}

function testPeek() {
  console.log("Testing peek method...");

  const cache = new Cache(3);
  cache.set('a', 1);
  cache.set('b', 2);
  cache.set('c', 3);

  // Test peek on existing key
  const value = cache.peek('b');
  if (value !== 2) {
    console.error("FAIL: peek should return the correct value");
    return false;
  }

  // Test that peek doesn't affect LRU order
  // Access 'a' to make it most recently used
  cache.get('a');

  // Peek 'c' - should still be in the same position
  const value2 = cache.peek('c');
  if (value2 !== 3) {
    console.error("FAIL: peek should return the correct value");
    return false;
  }

  // Verify LRU order is still correct (a should be first, then c, then b)
  const keys = cache.keys();
  if (keys[0] !== 'a' || keys[1] !== 'c' || keys[2] !== 'b') {
    console.error("FAIL: LRU order should not be affected by peek");
    return false;
  }

  // Test peek on non-existing key
  const value3 = cache.peek('nonexistent');
  if (value3 !== undefined) {
    console.error("FAIL: peek should return undefined for non-existing key");
    return false;
  }

  console.log("PASS: peek method works correctly");
  return true;
}

// Run all tests
console.log("Running Cache tests...\n");

let allPassed = true;
allPassed &= testDelete();
allPassed &= testClear();
allPassed &= testDeleteWithLRU();
allPassed &= testKeys();
allPassed &= testPeek();

if (allPassed) {
  console.log("\nAll tests passed!");
} else {
  console.log("\nSome tests failed!");
  process.exit(1);
}

